  const presignedUrl = await getSignedUrl(s3, command, { expiresIn: 3600 });

  return json({ clipId, downloadUrl: presignedUrl });
}

corrected_code:
import { json, LoaderFunctionArgs } from '@remix-run/node';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';
import { requireAuthUser } from '~/auth.server';
import { prisma } from '~/db.server';

const s3 = new S3Client({ region: 'us-east-1' });

export async function loader({ request, params }: LoaderFunctionArgs) {
  const user = await requireAuthUser(request);
  const { clipId } = params;

  const clip = await prisma.cameraClip.findFirst({
    where: { id: clipId, camera: { ownerId: user.id } }
  });
  if (!clip) {
    throw new Response('Access denied to requested video clip', { status: 403 });
  }

  const command = new GetObjectCommand({
    Bucket: 'smartcam-video-recordings',
    Key: `clips/${clipId}.mp4`,
  });
  const presignedUrl = await getSignedUrl(s3, command, { expiresIn: 3600 });

  return json({ clipId, downloadUrl: presignedUrl });
}
